--更新背包
---@param fishGoodsDojos FishingGoodsDojo[]
function FishingComponent:RefreshFishBackpack(fishGoodsDojos)
    if not fishGoodsDojos then
        return
    end
    for k, v in pairs(fishGoodsDojos) do
        local dojo = self._fishBackpack[checkString(v.goodsId)]
        --增加
        if checkNumber(v.num) > 0 then
            if not dojo then
                self._fishBackpack[checkString(v.goodsId)] = v
            else
                dojo.num = checkNumber(dojo.num) + checkNumber(v.num)
            end
        --减少
        else
            --不是基础道具才减
            --if not FishingUtils.IsBaseProps(v.goodsId) then
                dojo.num = checkNumber(dojo.num) + checkNumber(v.num)
                if dojo.num <= 0 then
                    self._fishBackpack[checkString(v.goodsId)] = nil
                end
            --end
        end
    end
end

--- 更新鱼篓
---@param fishingFishDojos FishingFishDojo[]
function FishingComponent:RefreshAllFish(fishingFishDojos)
    if not fishingFishDojos then
        return
    end
    for k, v in pairs(fishingFishDojos) do
        local dojo = self._allFish[checkString(v.fishId).."_"..checkString(v.rating)]
        --增加
        if checkNumber(v.num) > 0 then
            if not dojo then
                self._allFish[checkString(v.fishId).."_"..checkString(v.rating)] = v
            else
                dojo.num = checkNumber(dojo.num) + checkNumber(v.num)
            end
        --减少
        else
            dojo.num = checkNumber(dojo.num) + checkNumber(v.num)
            if dojo.num <= 0 then
                self._allFish[checkString(v.fishId).."_"..checkString(v.rating)] = nil
            end
        end
    end
end

---FishingCastingReq 抛竿
---@param placeId integer @ 钓场id
---@param result integer @ 1一般，2良好，3完美，与qte表一致
---@param cb fun(fishId:integer):void
---@param errCb fun():void
function FishingComponent:FishingCastingReq(placeId, result, cb, errCb)
    GameUtils.Request(Interfaces.FishingCasting, {placeId = placeId, result = result, isAuto = (self:IsAutoing() and 1 or 0)}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if errCb then
                errCb()
            end
            return
        end
        local jsonData = response.data
        if checkNumber(jsonData.fishId) <= 0 then
            if errCb then
                errCb()
            end
            return
        end
        self._fishTotal = self._fishTotal + 1
        local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
        if result == ConstantsFishing.CastRodType.Well then
            self._castingGoodNum = self._castingGoodNum + 1
        elseif result == ConstantsFishing.CastRodType.Perfect then
            self._castingPerfectNum = self._castingPerfectNum + 1
        end

        local dojo = clone(self:GetFishingGoodsDojo(self:GetCurEquipBaitId(placeId)))
        dojo.num = -1
        self:RefreshFishBackpack({dojo})
        dojo = clone(self:GetFishingGoodsDojo(self:GetCurEquipWireId(placeId)))
        dojo.num = -1
        self:RefreshFishBackpack({dojo})

        dojo = self:GetFishingGoodsDojo(self:GetCurEquipReelId(placeId))
        if dojo then
            if dojo.durability > 0 then
                dojo.durability = dojo.durability - 1
            end
        end

        dojo = self:GetFishingGoodsDojo(self:GetCurEquipRodId(placeId))
        if dojo then
            if dojo.durability > 0 then
                dojo.durability = dojo.durability - 1
            end
        end
        Events.Broadcast(Constants.EventNames.FishGoodsChange, {})
        
        if cb then
            cb(jsonData.fishId)
        end
    end)
end

---FishingCastingOverReq 收杆
---@param result integer @ 1成功，2断线，3挣脱
---@param cb fun(jsonData:table, lastExp:integer, lastLevel:integer):void
---@param consumeId number 消耗的道具id
function FishingComponent:FishingCastingOverReq(result, fishPlaceId, cb, consumeId, errCb)
    local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')
    if result == ConstantsFishing.FishFinishType.DisExceed then
        result = ConstantsFishing.FishFinishType.BreakLine
    end

    GameUtils.Request(Interfaces.FishingCastingOver, {result = result, isAuto = (self:IsAutoing() and 1 or 0) }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            errCb()
            return
        end

        --如果在钓鱼中  
        local FishingMgr = import('Game.UI.Fishing.FishingMgr')
        if FishingMgr:GetInstance():GetIsFishing() then
            return
        end

        local jsonData = response.data

        if result == ConstantsFishing.FishFinishType.BreakLine then
            self._fishCutOffFishNum = self._fishCutOffFishNum + 1
        elseif result == ConstantsFishing.FishFinishType.BreakFree then
            self._fishEscapeNum = self._fishEscapeNum + 1
        elseif result == ConstantsFishing.FishFinishType.Success then
            GoodsUtils.DrawRewards({ [1] = { goodsId = consumeId, num = -1} })
        end

        if checkNumber(jsonData.easterEgg) > 0 then
            self._easterEggs[checkString(jsonData.easterEgg)] = 1
        end

        local lastExp, lastLevel = self._curFishExp, self._curFishLevel
        self:RefreshExpAndLevel(jsonData.fishExp, jsonData.fishLevel)
        local t = jsonData.rewards
        local t1 = {}    --钓鱼里的道具
        local t2 = {}    --外面的道具
        for k, v in pairs(t) do
            local type = GoodsUtils.GetIdType(v.goodsId)
            if type == Constants.IDType.GoodsFishingRod or type == Constants.IDType.GoodsReel or type == Constants.IDType.GoodsBait or type == Constants.IDType.GoodsFishingLine then
                table.insert(t1, v)
            elseif type == Constants.IDType.RestaurantRecipeGoods then

            else
                table.insert(t2, v)
            end 
        end
        if table.count(t1) > 0 then
            self:RefreshFishBackpack(t1)
        end
        if table.count(t2) > 0 then
            GoodsUtils.DrawRewards(t2)
        end
        
        --鱼
        if checkNumber(jsonData.fishId) > 0 then
            local dojo = FishingFishDojo.New()
            dojo.fishId = checkNumber(jsonData.fishId)
            dojo.rating = checkNumber(jsonData.rating)
            dojo.num = 1
            self:RefreshAllFish({dojo})

            if checkNumber(jsonData.isNew) == 1 then
                self:AddNewPointFish(dojo.fishId)
                self._fishCollectedNum = self._fishCollectedNum + 1

                for k, v in pairs(self._fishPlaceInfo) do
                    if checkNumber(k) == checkNumber(fishPlaceId) then
                        v.collectNum = checkNumber(v.collectNum) + 1
                    end
                end
            end

            local dojo = FishingFishCollectionDojo.New()
            dojo.fishId = jsonData.fishId
            dojo.num = 1
            self._fishCollection[checkString(dojo.fishId)] = dojo
        end

        local vo = FishingUtils.GetFishingSpeciesVo(jsonData.fishId)
        if vo then
            local num = 0
            local ratingVo = FishingUtils.GetFishingRatingVo(jsonData.rating)
            if ratingVo then
                num = num + (math.floor(vo.price * (1 + ratingVo.priceAddition)) * 1)
            end
            --GoodsUtils.DrawRewards({ [1] = { goodsId = vo.currency, num = num} })
        end

        --活动积分
        if checkNumber(jsonData.activityScore) > 0 then
            for k, v in pairs(self._fishPlaceInfo) do
                if checkNumber(fishPlaceId) == checkNumber(k) then
                    if v.activity then                    
                        v.activity.score = checkNumber(v.activity.score) + checkNumber(jsonData.activityScore)
                        break
                    end
                end
            end
        end
        if FishingUtils.IsAutoing() then
            self:AddAutoRewards(jsonData)
            self._autoFinishNum = checkNumber(self._autoFinishNum) + 1
        end

        if cb then
            cb(jsonData, lastExp, lastLevel)
        end
    end)
end

--刷新经验和等级
function FishingComponent:RefreshExpAndLevel(exp, level)
    exp = checkNumber(exp)
    level = checkNumber(level)

    self._curFishExp = exp
    self._curFishLevel = level
end

---FishingAddPartnerReq 陪钓
---@param placeId integer @ 钓场id
---@param playerCardId integer @ 卡牌唯一id
---@param cb fun():void
function FishingComponent:FishingAddPartnerReq(placeId, playerCardId, cb)
    GameUtils.Request(Interfaces.FishingAddPartner, {placeId = placeId, playerCardId = playerCardId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local dojo = self:GetFishingPlaceDojo(placeId)
        if dojo then
            dojo.partner = checkNumber(playerCardId)
        else
            local dojo = FishingGoodsDojo.New()
            dojo.partner = checkNumber(playerCardId)
            self._fishPlaceInfo[checkString(placeId)] = dojo
        end
        if cb then 
            cb()
        end
    end)
end

---FishingReceiveScoreRewardsReq 领取积分奖励, 夏日活动的
---@param placeId integer @ 钓场id
---@param rewardId integer @ 
---@param cb fun():void
function FishingComponent:FishingReceiveScoreRewardsReq(placeId, rewardId, cb)
    local IsOpen = FishingUtils.IsActivityOpen(placeId)
    if not IsOpen then
        GameUtils.Toast(localize("活动已过期"))
        return
    end

    GameUtils.Request(Interfaces.FishingReceiveScoreRewards, {placeId = placeId, rewardId = rewardId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')

        local str = ""
        for k, v in pairs(self._fishPlaceInfo) do
            if checkNumber(placeId) == checkNumber(k) then
                if v.activity then
                    --没取到活动信息直接返回
                    local data = FishingUtils.GetFishPlaceDojoActivityData(placeId)
                    if not data then
                        return
                    end
                    local rewardsT = checkTable(data.receivedScoreRewards)

                    --一键
                    if checkNumber(rewardId) == 0 then
                        local t = FishingUtils.GetAllCanDrawIntegralRewardId(placeId) 
                        if t then
                            for _, _id in pairs(t) do
                                table.insert(rewardsT, checkString(_id))
                            end
                        end
                    else
                        table.insert(rewardsT, checkString(rewardId))
                    end
                    
                    --for _, _act in pairs(v.activity) do
                        local vo = FishingUtils.GetFishActivityPlanVo(v.activity.contentId)
                        if vo then
                            if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                                v.activity.receivedScoreRewards = rewardsT
                                break
                            end
                        end
                    --end
                end
            end
        end
        
        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        if cb then 
            cb()
        end
    end)
end

---FishingReceiveTicketReq 领取活动钓鱼劵
---@param placeId integer @ 钓场id
---@param cb fun():void
function FishingComponent:FishingReceiveTicketReq(placeId, cb, errCb)
    local isOpen = FishingUtils.IsActivityOpen(placeId)
    if not isOpen then
        GameUtils.Toast(localize("活动已过期"))
        if errCb then 
            errCb()
        end
        return
    end
    
    GameUtils.Request(Interfaces.FishingReceiveTicket, {placeId = placeId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        for k, v in pairs(self._fishPlaceInfo) do
            if checkNumber(placeId) == checkNumber(k) then
                if v.activity then                    
                    v.activity.receivedTicket = 1
                end
            end
        end

        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards, cb = function()
            if cb then 
                cb()
            end
        end} })
    end)
end

---FishingSwitchTicketReq 切换活动钓鱼劵
---@param placeId integer @ 钓场id
---@param type integer 1普通，2活动
---@param cb fun():void
function FishingComponent:FishingSwitchTicketReq(placeId, type, cb)
    local isOpen = FishingUtils.IsActivityOpen(placeId)
    if not isOpen then
        GameUtils.Toast(localize("活动已过期"))
        return
    end

    type = checkNumber(type)
    if type == 0 then
        return
    end
    GameUtils.Request(Interfaces.FishingSwitchTicket, {placeId = placeId, type = type}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')

        for k, v in pairs(self._fishPlaceInfo) do
            if checkNumber(placeId) == checkNumber(k) then
                if v.activity then                    
                    --for _, _act in pairs(v.activity) do
                        local vo = FishingUtils.GetFishActivityPlanVo(v.activity.contentId)
                        if vo then
                            if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                                if type == ConstantsFishing.ActivityType.Common then
                                    v.activity.useTicket = 0
                                else
                                    v.activity.useTicket = 1
                                end

                                break
                            end
                        end
                    --end
                end
            end
        end

        if cb then 
            cb()
        end
    end)
end

---FishingExchangeTicketReq 兑换活动钓鱼劵
---@param useId integer @ 兑换表id
---@param times integer @ 兑换次数
---@param cb fun():void
function FishingComponent:FishingExchangeTicketReq(placeId, useId, times, cb)
    local isOpen = FishingUtils.IsActivityOpen(placeId)
    if not isOpen then
        GameUtils.Toast(localize("活动已过期"))
        return
    end
    useId = checkNumber(useId)
    times = checkNumber(times)

    if times <= 0 then
        return
    elseif useId <= 0 then
        return
    end
    GameUtils.Request(Interfaces.FishingExchangeTicket, {useId = useId, times= times, placeId = placeId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local ConstantsFishing = import('Game.UI.Fishing.ConstantsFishing')

        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        local vo = FishingUtils.GetFishExchangeVo(useId)
        if vo then
            local t = {
                {
                    goodsId = checkNumber(vo.cost),
                    num = checkNumber(vo.costNum) * times * -1
                }
            }

            GoodsUtils.DrawRewards(t)
        end

        for k, v in pairs(self._fishPlaceInfo) do
            if checkNumber(placeId) == checkNumber(k) then
                if v.activity then                    
                    --for _, _act in pairs(v.activity) do
                        print(v.activity.contentId)
                        local vo = FishingUtils.GetFishActivityPlanVo(v.activity.contentId)
                        if vo then
                            if checkNumber(vo.activity) == ConstantsFishing.ActivityType.Summer then
                                local remainNum = checkNumber(v.activity.remainExchangeTimes[checkString(useId)]) - times
                                v.activity.remainExchangeTimes[checkString(useId)] = remainNum
                                --v.activity.remainExchangeTimes = checkNumber(v.activity.remainExchangeTimes) - times
                            end
                        end
                    --end
                end
            end
        end

        if cb then 
            cb()
        end
    end)
end

---FishingEquipReq 装备
---@param goodsId integer @ 道具id
---@param cb fun(lastEquipId:integer):void
function FishingComponent:FishingEquipReq(goodsId, cb, placeId)
    print("装备")

    GameUtils.Request(Interfaces.FishingEquip, {goodsId = goodsId, placeId = placeId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        
        local lastEquipId
        local type = GoodsUtils.GetIdType(goodsId)
        if type == Constants.IDType.GoodsFishingRod then
            lastEquipId = self._equipRod[checkString(placeId)]
            self._equipRod[checkString(placeId)] = goodsId
        elseif type == Constants.IDType.GoodsReel then
            lastEquipId = self._equipWheel[checkString(placeId)]  
            self._equipWheel[checkString(placeId)] = goodsId
        elseif type == Constants.IDType.GoodsBait then
            lastEquipId = self._equipBait[checkString(placeId)]
            self._equipBait[checkString(placeId)] = goodsId
        elseif type == Constants.IDType.GoodsFishingLine then
            lastEquipId = self._equipWire[checkString(placeId)]
            self._equipWire[checkString(placeId)] = goodsId
        end 

        if cb then
            cb(lastEquipId)
        end
        --Events.Broadcast(Constants.EventNames.FishGoodsChange, {})
    end)
end

---FishingBuyReq 购买
---@param goodsId integer @ 道具id
---@param num integer @ 道具num
---@param cb fun():void
function FishingComponent:FishingBuyReq(goodsId, num, cb)
    print("购买")

    local vo = FishingUtils.GetFishingGoodsVoById(goodsId)
    if not vo then
        GameUtils.Toast(localize("未找到该物品"))
        return 
    elseif checkNumber(vo.isStoreGood) == 0 then
        GameUtils.Toast(localize("该物品无法购买"))
        return 
    else
        local isUnlock = FishingUtils.isUnlockGoods(goodsId)
        if not isUnlock then
            local placeVo = FishingUtils.GetFishingPlaceVo(vo.needLevel)
            if not placeVo then
                printError(string.format('--->>>查不找鱼场配置 %s %s', vo.needLevel, vo.id))
            else
                local err = localize("钓场_num_解锁", {_num_ = placeVo.name})
                CfUtils.FillText(self.TextLock, err)
            end
            return
        end

        --local curLevel, exp = FishingUtils.GetCurLevelAndExp()
        --if checkNumber(vo.needLevel) > checkNumber(curLevel) then
        --    GameUtils.Toast(localize("钓鱼等级_num_解锁", {_num_ = checkNumber(vo.needLevel)}))
        --    return 
        --end
    end
    local isCanBuy = (GoodsUtils.GetThingNo(vo.currency) >= checkNumber(vo.price))
    if not isCanBuy then
        GameUtils.Toast(localize("购买费用不够"))
        return 
    end

    GameUtils.Request(Interfaces.FishingBuy, {goodsId = goodsId, num = num}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local dojo = FishingGoodsDojo.New()
        dojo.goodsId = goodsId
        dojo.num = num
        local vo = FishingUtils.GetFishingGoodsVoById(goodsId)
        if vo then
            dojo.durability = checkNumber(vo.durability)
        end
        self:RefreshFishBackpack({dojo})

        local rewards = {
            {goodsId = vo.currency, num = checkNumber(vo.price) * num * -1}
        }
        GoodsUtils.DrawRewards(rewards)

        Events.Broadcast(Constants.EventNames.FishGoodsChange, {})
        if cb then
            cb()
        end
    end)
end

---FishingFixReq 维修
---@param goodsId integer @ 道具id
---@param cb fun():void
function FishingComponent:FishingFixReq(goodsId, cb, errCb)
    print("维修")
    local function CheckCanFix()
        local dojo = self:GetFishingGoodsDojo(goodsId)
        if not dojo then
            GameUtils.Toast(localize("未拥有该物品"))
            return false
        end

        local vo = FishingUtils.GetFishingGoodsVoById(goodsId)
        if not vo then
            GameUtils.Toast(localize("未找到该物品"))
            return false
        elseif checkNumber(vo.durability) <= 0 then
            GameUtils.Toast(localize("该物品无法维修"))
            return false
        end

        if checkNumber(dojo.durability) == checkNumber(vo.durability) then
            GameUtils.Toast(localize("耐久度是满的"))
            return false
        end

        local consumeNum = FishingUtils.GetFixConsumeNum(goodsId)
        local isCanFix = (GoodsUtils.GetThingNo(vo.fixCurrency) >= checkNumber(consumeNum))
        if not isCanFix then
            GameUtils.Toast(localize("维修费用不够"))
            return false
        end
        return true
    end
    local canFix = CheckCanFix()
    if not canFix then
        if errCb then
            errCb()
        end
        return
    end
    

    GameUtils.Request(Interfaces.FishingFix, {goodsId = goodsId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if errCb then
                errCb()
            end
            return
        end
        local vo = FishingUtils.GetFishingGoodsVoById(goodsId)
        local consumeNum = FishingUtils.GetFixConsumeNum(goodsId)
        local dojo = self:GetFishingGoodsDojo(goodsId)
        if dojo then
            dojo.durability = checkNumber(vo.durability) 
        end

        local rewards = {
            {goodsId = vo.fixCurrency, num = checkNumber(consumeNum) * -1}
        }
        GoodsUtils.DrawRewards(rewards)

        Events.Broadcast(Constants.EventNames.FishGoodsChange, {})
        if cb then
            cb()
        end
    end)
end

---FishingSaleReq 卖鱼
---@param data table @ jsonData {["fishId":1,"rating":1,"num":1]}
---@param cb fun():void
function FishingComponent:FishingSaleReq(data, cb)
    if not data then
        return
    end
    local info = table.serialize(data)

    GameUtils.Request(Interfaces.FishingSale, {info = info}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        --扣除鱼数据
        for k, v in pairs(data) do
            v.num = checkNumber(v.num) * -1
        end
        self:RefreshAllFish(data)
        GoodsUtils.DrawRewards(jsonData.rewards)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })

        Events.Broadcast(Constants.EventNames.FishBasketChange, {})
        if cb then
            cb()
        end
    end)
end

---FishingMakeReq 制饵
---@param data table @ jsonData {["fishId":1,"rating":1,"num":1]}
---@param cb fun():void
function FishingComponent:FishingMakeReq(data, cb)
    if not data then
        return
    end
    local info = table.serialize(data)
    GameUtils.Request(Interfaces.FishingMake, {info = info}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        --扣除鱼数据
        for k, v in pairs(data) do
            v.num = v.num * -1
        end
        self:RefreshAllFish(data)

        local t = {}
        for k, v in pairs(jsonData.baits) do
            local dojo = FishingGoodsDojo.New()
            dojo.goodsId = checkNumber(v.baitId)
            dojo.num = checkNumber(v.num)
            table.insert(t, dojo)
        end
        self:RefreshFishBackpack(t)
        Events.Broadcast(Constants.EventNames.FishBasketChange, {})

        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = t}})
        if cb then
            cb()
        end
    end)
end

--图鉴收集
---@param cb fun():void
function FishingComponent:FishingCollectionReq(cb)
    GameUtils.Request(Interfaces.FishingCollection, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._fishCollection = {}
        local t = checkTable(jsonData.collection)  
        for k, v in pairs(t) do
