--挂机
---@param cb fun():void
function FishingComponent:FishingHangUpReq(cb)
    GameUtils.Request(Interfaces.FishingOfflineHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._fishTeamInfo = {}
        local t = checkTable(jsonData.teamInfo)  
        for k, v in pairs(t) do
            local dojo = FishingFishHangUpQueueDojo.New()
            dojo:Fill(v)
            dojo.teamId = k
            self._fishTeamInfo[checkString(k)] = dojo
        end 
        self._fishCardsInfo = {}
        for k, v in pairs(checkTable(jsonData.cardsInfo)) do
            local data = cardComp:GetCardById(k)
            if data then
                local vo = FishingUtils.GetFishingCardBonusVo(data.cardId)
                if vo then
                    self._fishCardsInfo[k] = {
                        num = checkNumber(v),
                        remainTime = (checkNumber(vo.energy) - checkNumber(v)) * checkNumber(vo.time)          --恢复时间
                    }
                end
            end
        end

        --self:StartTimeDown()
        if cb then
            cb()
        end
    end)
end

---FishingOfflineStartReq 开始挂机
---@param placeId number @ 钓场id
---@param teamId number @ 队伍id
---@param times number @ 钓鱼次数
---@param cb fun():void
function FishingComponent:FishingOfflineStartReq(placeId, teamId, times, cb)
    GameUtils.Request(Interfaces.FishingOfflineStart, {placeId = placeId, teamId = teamId, times = times}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local dojo = self:GetHangUpDojoByQueueId(teamId)
        if dojo then
            local FishingUtils = import('Game.UI.Fishing.FishingUtils')
            dojo.placeId = placeId
            dojo.totalTimes = checkNumber(times)
            dojo.remainTime = checkNumber(times) * FishingUtils.GetFishHangUpTime()
            dojo.rewards = {}
            dojo.fish = {}
        end
        Events.Broadcast(Constants.EventNames.FishBasketChange, {})

        if cb then
            cb()
        end
    end)
end

---FishingOfflineEndReq 挂机结束或领取
---@param teamId number @ 队伍id
function FishingComponent:FishingOfflineEndReq(teamId)
    GameUtils.Request(Interfaces.FishingOfflineEnd, {teamId = teamId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local dojo = self:GetHangUpDojoByQueueId(teamId)
        if dojo then
            dojo.placeId = 0
            dojo.totalTimes = 0
            dojo.remainTime = 0
            dojo.rewards = {}
            dojo.fish = {}
        end

        if table.count(jsonData.fish) >= 0 then
            self:RefreshAllFish(jsonData.fish)
        end

        local t = clone(jsonData.fish)
        for k, v in pairs(t) do
            v.goodsId = v.fishId
        end

        local _t = jsonData.rewards
        if table.count(_t) > 0 then
            GoodsUtils.DrawRewards(_t)
            for k, v in pairs(_t) do
                table.insert(t, v)
            end
        end
        if table.count(t) > 0 then
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = t } })
        end

        Events.Broadcast(Constants.EventNames.FishBasketChange, {})
    end)
end

---ChangeOffLineCardsReq 跟换挂机队伍
---@param cards string @ 卡牌唯一id,逗号分隔
---@param queueId number @ 队列id 
---@param cb fun():void
function FishingComponent:ChangeOffLineCardsReq(queueId, data, cb)
    if not data or checkNumber(queueId) == 0 then
        return
    end
    local cardsStr = ""
    for k, v in pairs(data) do
        cardsStr = cardsStr..checkNumber(v.refId)
        if k < table.count(data) then
            cardsStr = cardsStr..","
        end
    end

    GameUtils.Request(Interfaces.FishingOfflineSetTeam, {teamId = queueId, cards = cardsStr}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data


        local dojo = self:GetHangUpDojoByQueueId(queueId)
        if not dojo then
            local dojo = FishingFishHangUpQueueDojo.New()
            dojo.teamId = queueId
            dojo.cards = cardsStr
            self._fishTeamInfo[checkString(queueId)] = dojo
        else
            dojo.cards = cardsStr
        end
        if cb then
            cb()
        end
    end)
end



---FishingGetChallengeTaskListReq 
function FishingComponent:FishingGetChallengeTaskListReq(placeId, cb)
    GameUtils.Request(Interfaces.FishingGetChallengeTaskList, {placeId = placeId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        self._allTaskData = checkTable(jsonData.task)
        self._remainFreeRefreshTimes = checkNumber(jsonData.remainFreeRefreshTimes)
        self._remainTaskSubmitTimes = checkNumber(jsonData.remainTaskSubmitTimes)

        if cb then
            cb()
        end
    end)
end

---FishingRefreshChallengeTaskReq 
function FishingComponent:FishingRefreshChallengeTaskReq(realTaskId, cb)
    GameUtils.Request(Interfaces.FishingRefreshChallengeTask, {realTaskId = realTaskId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        if checkNumber(jsonData.newTask.realTaskId) > 0 then
            local ind = 0
            for k, v in pairs(self._allTaskData) do
                if checkNumber(realTaskId) == checkNumber(v.realTaskId) then
                    ind = k
                end
            end
            if ind > 0 then
                table.remove(self._allTaskData, ind)
                table.insert(self._allTaskData, ind, checkTable(jsonData.newTask))
            end
        end

        self._remainFreeRefreshTimes = checkNumber(jsonData.remainFreeRefreshTimes)

        if cb then
            cb(jsonData.newTask.realTaskId)
        end
    end)
end

---FishingChallengeTaskDrawReq 
function FishingComponent:FishingChallengeTaskDrawReq(realTaskId, cb)
    GameUtils.Request(Interfaces.FishingChallengeTaskDraw, {realTaskId = realTaskId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        for k, v in pairs(self._allTaskData) do
            if checkNumber(realTaskId) == checkNumber(v.realTaskId) then
                v.status = 2
            end
        end

        if checkNumber(jsonData.newTask.realTaskId) > 0 then
            local ind = 0
            for k, v in pairs(self._allTaskData) do
                if checkNumber(realTaskId) == checkNumber(v.realTaskId) then
                    ind = k
                end
            end
            if ind > 0 then
                table.remove(self._allTaskData, ind)
                table.insert(self._allTaskData, ind, checkTable(jsonData.newTask))
            end
        end

        GoodsUtils.DrawRewards(jsonData.rewards)
        self._remainTaskSubmitTimes = checkNumber(jsonData.remainTaskSubmitTimes)

        if cb then
            cb(jsonData.newTask.realTaskId, jsonData.rewards)
        end
    end)
end

