function FishingComponent:FishingChallengeExchangeReq(exchangeId, cb)
    GameUtils.Request(Interfaces.FishingChallengeExchange, {exchangeId = exchangeId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local vo = FishingUtils.GetFishingExChangeVo(exchangeId)
        --这个类型一直能
