--开始倒计时
function FishingComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        --[[
        for k, v in pairs(self._fishTeamInfo) do
            if checkNumber(v.remainTime) > 0 then
                v.remainTime = checkNumber(v.remainTime) - 1
            end 
        end

        --恢复精力
        for k, v in pairs(self._fishCardsInfo) do
            if v.remainTime > 0 then
                v.remainTime = v.remainTime - 1
            end

            local data = cardComp:GetCardById(k)
            if self:IsCardCanFishing(data.cardId) then
                local vo = FishingUtils.GetFishingCardBonusVo(data.cardId)
                if vo then
                    if (v.remainTime % checkNumber(vo.time)) == 0 then
                        --小于恢复
                        if checkNumber(v.num) < checkNumber(vo.energy) then
                            local curEnergy = checkNumber(v.num) + 1
                            curEnergy = math.min(curEnergy, checkNumber(vo.energy))
                            v.num = curEnergy
                        end
                    end
                end
            end
        end
        Events.Broadcast(Constants.EventNames.FishHangUpTimeDown, {})
        ]]

        for k, v in pairs(self._fishPlaceInfo) do
            if not isNull(v.activity) and checkNumber(v.activity.contentId) > 0 then
                --for _, _act in pairs(v.activity) do
                    --活动结束
                    if checkNumber(v.activity.remainTime) == 0 then 
                        Events.Broadcast(Constants.EventNames.FishActivityClose, {placeId = v.id, activityId = v.activity.contentId})
                    end
                    v.activity.remainTime = checkNumber(v.activity.remainTime) - 1
                --end
            end
        end
    end, CountDownTime, false, true)
end

