---GetMaxFishingPlaceId
---获得解锁的鱼场中的最大id
function FishingComponent:GetMaxFishingPlaceId()
    local placeId = 0
    if self._fishPlaceInfo then
        for fishPlaceId, v in pairs(self._fishPlaceInfo) do
            if checkNumber(v.isUnlock) == 1 then
                ---如果是已解锁的鱼场
                if checkNumber(fishPlaceId) > placeId then
                    placeId = checkNumber(fishPlaceId)
                end
            end
        end
    end
    return placeId
end

