---IsHangeUpQueueHasTask 该队列是否有任务
---@param queueId integer @ 队列id
---@return boolean
function FishingComponent:IsHangeUpQueueHasTask(queueId)
    if checkNumber(queueId) == 0 then
        return false
    end
    local dojo = self:GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return false
    end
    return (checkNumber(dojo.placeId) ~= 0)
end

---IsHangeUpQueueFinishTask 该队列是否完成任务
---@param queueId integer @ 队列id
---@return boolean
function FishingComponent:IsHangeUpQueueFinishTask(queueId)
    if checkNumber(queueId) == 0 then
        return false
    end
    --没任务直接返回
    if not self:IsHangeUpQueueHasTask(queueId) then
        return false
    end
    local dojo = self:GetHangUpDojoByQueueId(queueId)
    if not dojo then
        return false
    end

    return (checkNumber(dojo.remainTime) <= 0)
end

--获取等级和队列解锁对照map
function FishingComponent:GetHangUpLevelContrast()
    if not self._hangUpLevelContrast then
        local t = CfUtils.GetCfTable(AutoIds.IdSetting1843)
        self._hangUpLevelContrast = {}
        if t then
            for k, v in pairs(t) do
                local levelkey = parse_string(v, "level")
                local idValue = parse_number(v, "id")
                self._hangUpLevelContrast[levelkey] = idValue
            end
        end
    end
    return self._hangUpLevelContrast
end

---IsCardCanFishing 该卡牌是否可以钓鱼
---@param cardId integer @ 卡牌id
---@return boolean
function FishingComponent:IsCardCanFishing(cardId)
    if not self._allFishCards  then
        self._allFishCards = {}
        local t = CfUtils.GetCfTable(AutoIds.IdSetting1847)
        if t then
            for k, v in pairs(t) do
                local id = parse_string(v, "id")
                self._allFishCards[id] = 1
            end
        end
    end
    
    return (checkNumber(self._allFishCards[checkString(cardId)]) == 1)
end

---IsFishNew 是否有小红点
---@param fishId integer @ 渔id
---@return boolean
function FishingComponent:IsFishNew(fishId)
    if checkNumber(fishId) <= 0 then
        return false
    elseif not self._fishNewPointData then
        return false
    end
    return (checkNumber(self._fishNewPointData[checkString(fishId)]) == 1)
end

--添加一份小红点数据
function FishingComponent:AddNewPointFish(fishId)
    if checkNumber(fishId) <= 0 then
        return
    end
    if not self._fishNewPointData then
        self._fishNewPointData = {}
    end
    self._fishNewPointData[checkString(fishId)] = 1
end

--删除一份小红点数据
function FishingComponent:DelNewPointFish(fishId)
    if checkNumber(fishId) <= 0 then
        return
    elseif not self._fishNewPointData then
        return 
    end
    self._fishNewPointData[checkString(fishId)] = nil
end

