--- 领取彩蛋宝箱奖励
---@param groupId integer
---@param cb fun(rewards:table):void
function FishingComponent:DrawEasterEggsGroupRewards(groupId, cb)
    GameUtils.Request(Interfaces.FishingReceiveEasterEggsGroupRewards, {groupId = groupId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        GoodsUtils.DrawRewards(jsonData.rewards)

        self._easterEggsGroupReceived[checkString(groupId)] = 1
        if cb then
            cb(jsonData.rewards)
        end
    end)
end

function FishingComponent:DrawAtlasRewards(boxId, placeId, cb)
    GameUtils.Request(Interfaces.FishingReceiveCollectionRewards, {boxId = boxId, placeId = placeId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        GoodsUtils.DrawRewards(jsonData.rewards)

        self._atlasReceived[checkString(boxId)] = 1
        if cb then
            cb(jsonData.rewards)
        end
    end)
end

function FishingComponent:GetAutoNum()
