end

function FishingComponent:AutoFishReq(num, placeId, cb)
    self._autoNum = checkNumber(num)
    self._autoFinishNum = 0
    self._isAutoing = true
    self._isAutoEnd = nil
    
    if cb then
        cb()
    end
end

