    --self._isAutoing = false
    self._isAutoEnd = true
    if cb then
        cb()
    end
end

function FishingComponent:GetIsAutoEnd()
    local b = self._isAutoEnd
    return b
end

function FishingComponent:SetAutoing(b)
    self._isAutoing = b

    --这个值为false 代表页面逻辑需要用的值已完全结束
    if not b then
        self._isAutoEnd = nil
    end
end

function FishingComponent:IsAutoing()
    return self._isAutoing
end

function FishingComponent:AddAutoRewards(data)
    if not self._autoRewards then
        self._autoRewards = {}
    end

    local t = checkTable(data.rewards)
    for k, v in pairs(t) do
        if self._autoRewards[checkString(v.goodsId)] then
            self._autoRewards[checkString(v.goodsId)].num = checkNumber(self._autoRewards[checkString(v.goodsId)].num) + checkNumber(v.num)
        else
            self._autoRewards[checkString(v.goodsId)] = v
        end
    end
end

function FishingComponent:GetAutoRewards()
    local t = checkTable(self._autoRewards)
    local _t = {}
    for k, v in pairs(t) do
        table.insert(_t, v)
    end

    self._autoRewards = {}
    return _t
end

function FishingComponent:NetFishReq(fishPlaceId, goodsCount, cb)
    local requestData = {
        placeId = checkNumber(fishPlaceId),
        useNetNum = checkNumber(goodsCount)
    }
    GameUtils.Request(Interfaces.OverseaGoFishNetting, requestData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = checkTable(response.data)

        if cb then
            cb(jsonData.rewards, jsonData.newGetCollectionFishingIds)
        end
    end)
end

return FishingComponent